import {evaluate,formatResult} from './calculator-engine.js?v=13';
import {fields,serialize,NaturalEditor,boundaryField} from './calculator-tree.js?v=13';
let remembered='basic';try{remembered=sessionStorage.getItem('calculator-mode')||'basic'}catch{}
let answer={value:0,exact:[0n,1n]},memory=Object.fromEntries(['A','B','C','D','E','F','x','y','M'].map(k=>[k,0]));
export function mountCalculator(host,{language=()=> 'en',onClose=()=>{host.hidden=true}}={}){
 const natural=new NaturalEditor();
 const tr=(a,b)=>language()==='bm'?b:a;let shifted=false,alpha=false,panelMode=null,engineering=null;let mode=['basic','scientific','natural'].includes(remembered)?remembered:'basic',angle='DEG',text='',tree=natural.root,active=natural.id,selection=[0,0],result=null,exact=false,error='';
 const el=(tag,cls='',label)=>{const n=document.createElement(tag);n.className=cls;if(label!==undefined)n.textContent=label;return n};
 const names={'+':['Add','Tambah'],'−':['Subtract','Tolak'],'×':['Multiply','Darab'],'÷':['Divide','Bahagi'],'=':['Equals','Sama dengan'],'.':['Decimal point','Titik perpuluhan'],'(':['Open parentheses','Buka kurungan'],')':['Close parentheses','Tutup kurungan'],'±':['Change sign','Tukar tanda'],'%':['Percent','Peratus'],'Ans':['Previous answer','Jawapan sebelumnya'],'C':['Clear','Kosongkan'],'DEL':['Delete','Padam'],'SHIFT':['Shift functions','Fungsi Shift'],'OUT':['Exit template','Keluar templat'],'mixed':['Mixed fraction','Pecahan bercampur'],'x³':['Cube','Kuasa tiga'],'a/b':['Fraction','Pecahan'],'xʸ':['Power','Kuasa'],'x²':['Square','Kuasa dua'],'√':['Square root','Punca kuasa dua'],'ⁿ√':['Nth root','Punca ke-n'],'1/x':['Reciprocal','Salingan'],'π':['Pi','Pi'],'e':['Euler constant','Pemalar Euler'],'!':['Factorial','Faktorial'],'10ˣ':['Power of ten','Kuasa sepuluh'],'eˣ':['Exponential','Eksponen'],'×10ⁿ':['Scientific notation','Notasi saintifik'],'←':['Cursor left','Kursor kiri'],'→':['Cursor right','Kursor kanan'],'↑':['Cursor up','Kursor atas'],'↓':['Cursor down','Kursor bawah'],'sin':['Sine','Sinus'],'cos':['Cosine','Kosinus'],'tan':['Tangent','Tangen'],'asin':['Inverse sine','Sinus songsang'],'acos':['Inverse cosine','Kosinus songsang'],'atan':['Inverse tangent','Tangen songsang'],'log':['Base ten logarithm','Logaritma asas sepuluh'],'ln':['Natural logarithm','Logaritma asli'],'abs':['Absolute value','Nilai mutlak']};
 Object.assign(names,{'∫':['Definite integral','Kamiran tentu'],'d/dx':['Derivative','Terbitan'],'logₐ':['Logarithm with base','Logaritma dengan asas'],'°′″':['Degrees minutes seconds','Darjah minit saat'],STO:['Store variable','Simpan pemboleh ubah'],RCL:['Recall variable','Panggil pemboleh ubah'],CALC:['Calculate with variables','Kira dengan pemboleh ubah'],OPTN:['Function options','Pilihan fungsi'],MENU:['Calculator settings','Tetapan kalkulator'],ON:['On / clear','Hidup / kosongkan'],ALPHA:['Alpha variables','Pemboleh ubah Alpha'],ENG:['Engineering notation','Notasi kejuruteraan']});
 const label=k=>names[k]?tr(...names[k]):k;
 function btn(k,fn,visible=k){const b=el('button','',visible);b.type='button';b.title=b.ariaLabel=label(k);b.onpointerdown=e=>e.preventDefault();b.onclick=fn;return b;}
 function syncNatural(){tree=natural.root;active=natural.id;selection=[...natural.selection];}
 function paint(input,value){host.querySelectorAll('.math-caret').forEach(c=>c.remove());host.querySelectorAll('.math-boundary').forEach(f=>{if(f===input)f.removeAttribute('aria-hidden');else f.setAttribute('aria-hidden','true');});const pos=Math.min(selection[0],value.length);input.replaceChildren(document.createTextNode(value.slice(0,pos)));const caret=el('span','math-caret','│');caret.setAttribute('aria-hidden','true');input.append(caret,document.createTextNode(value.slice(pos)||' '));input.setAttribute('aria-valuetext',value||'0');}
 function focus(id=active,pos){const input=mode==='natural'?host.querySelector(`[data-field="${id}"]`):host.querySelector('.calc-linear');if(input){active=id;const value=mode==='natural'?fields(tree).find(f=>f.id===id)?.text||'':text;const p=pos??value.length;selection=[p,p];if(mode==='natural')natural.focus(id,p);paint(input,value);input.focus({preventScroll:true});}}
 function display(cls,value,id,label){const i=el('div',cls);i.tabIndex=0;i.setAttribute('role','textbox');i.setAttribute('aria-readonly','true');i.ariaLabel=label;if(id)i.dataset.field=id;i.textContent=value||' ';i.dataset.empty=String(!value);i.onclick=()=>focus(id||active);i.onfocus=()=>{if(id&&active!==id){active=id;selection=[value.length,value.length];}if(mode==='natural')natural.focus(id,selection[0]);paint(i,mode==='natural'?fields(tree).find(f=>f.id===id)?.text||'':text);};return i;}
 function output(){host.querySelectorAll('[data-key="S⇔D"]').forEach(b=>{b.disabled=!result?.exact;b.setAttribute('aria-pressed',String(exact));});const t=host.querySelector('.calc-exact');t.disabled=!result?.exact;t.setAttribute('aria-pressed',String(exact));const out=host.querySelector('.calc-result');out.replaceChildren();if(error){const errors={syntax:['Check the expression.','Semak ungkapan.'],zero:['Cannot divide by zero.','Tidak boleh bahagi dengan sifar.'],domain:['Outside the function’s valid range.','Di luar julat fungsi yang sah.'],limit:['Expression is too long.','Ungkapan terlalu panjang.']};out.textContent=tr(...(errors[error]||errors.syntax));return;}if(!result){out.textContent=tr('Result','Hasil');return;}if(exact&&result.exact&&result.exact[1]!==1n&&mode==='natural'){const f=el('span','calc-fraction');f.append(el('span','',String(result.exact[0])),el('span','',String(result.exact[1])));out.append(f);}else out.textContent=engineering!==null?`${Number((result.value/10**engineering).toPrecision(10))} × 10^${engineering}`:formatResult(result,exact);const toggle=host.querySelector('.calc-exact');toggle.disabled=!result.exact;toggle.setAttribute('aria-pressed',String(exact));}
 function solve(){engineering=null;try{result=evaluate(mode==='natural'?serialize(tree):text,{angle,ans:answer,variables:memory});answer=result;error='';}catch(e){error=e.message;result=null;}output();}
 function treeDOM(node,path=tr('Expression','Ungkapan'),parent=null){if(node.type==='Text'){const i=display('math-slot',node.text,node.id,path);if(boundaryField(parent,node)){i.classList.add('math-boundary');i.tabIndex=-1;if(node.id!==active)i.setAttribute('aria-hidden','true');}else if(!node.text)i.classList.add('math-placeholder');return i;}
 const box=el('span','math-'+node.type.toLowerCase());if(node.type==='Sequence'){node.children.forEach(x=>box.append(treeDOM(x,path,node)));}else if(node.type==='Integral'||node.type==='Derivative'){if(node.type==='Integral'){const limits=el('span','integral-limits');limits.append(treeDOM(node.upper,tr('Upper limit','Had atas')),el('span','integral-symbol','∫'),treeDOM(node.lower,tr('Lower limit','Had bawah')));box.append(limits,treeDOM(node.body,tr('Expression in x','Ungkapan dalam x')),el('span','','dx'));}else box.append(el('span','','d/dx('),treeDOM(node.body,tr('Expression in x','Ungkapan dalam x')),el('span','',') x = '),treeDOM(node.at,tr('At x','Pada x')));}else if(node.type==='LogBase'){box.append(el('span','','log'),treeDOM(node.base,tr('Logarithm base','Asas logaritma')),el('span','','('),treeDOM(node.body,tr('Argument','Argumen')),el('span','',')'));}else if(node.type==='DMS'){for(const [part,unit]of [['degrees','°'],['minutes','′'],['seconds','″']])box.append(treeDOM(node[part],unit),el('span','',unit));}else if(node.type==='Fraction'){box.append(treeDOM(node.numerator,tr('Numerator','Pengangka')),treeDOM(node.denominator,tr('Denominator','Penyebut')));}else if(node.type==='Mixed'){box.append(treeDOM(node.whole,tr('Whole number','Nombor bulat')));const fraction=el('span','math-fraction');fraction.append(treeDOM(node.numerator,tr('Numerator','Pengangka')),treeDOM(node.denominator,tr('Denominator','Penyebut')));box.append(fraction);}else if(node.type==='Power'){box.append(treeDOM(node.base,tr('Base','Asas')),treeDOM(node.exponent,tr('Exponent','Eksponen')));}else if(node.type==='Root'||node.type==='Sqrt'){if(node.index)box.append(treeDOM(node.index,tr('Root index','Indeks punca')));box.append(el('span','radical','√'),treeDOM(node.body,tr('Inside root','Dalam punca')));}else{box.append(el('span','',node.type==='Function'?node.name+'(':'('),treeDOM(node.body,path),el('span','',')'));}return box;}
 function add(value){error='';result=null;if(mode==='natural'){natural.type(value);syncNatural();render();focus(active,selection[0]);return;}const [a,b]=selection;text=text.slice(0,a)+value+text.slice(b);render();focus(active,a+value.length);}
 function key(k){if(['MENU','OPTN','CALC','STO','RCL'].includes(k)){panelMode=panelMode===k?null:k;shifted=alpha=false;render();return;}if(k==='ON'||k==='OFF'){if(k==='OFF'){onClose();return;}k='C';}if(k==='ALPHA'){alpha=!alpha;shifted=false;render();focus(active,selection[0]);return;}if(k==='S⇔D'){exact=!exact;output();return;}if(k==='ENG'||k==='ENG←'){if(!result)solve();if(result){engineering=engineering===null?(result.value?Math.floor(Math.log10(Math.abs(result.value))/3)*3:0):engineering+(k==='ENG←'?3:-3);output();}shifted=false;render();return;}if(k==='M+'||k==='M−'){solve();if(result)memory.M+=(k==='M+'?1:-1)*result.value;shifted=false;render();return;}alpha=false;engineering=null;if(k==='='){solve();return;}if(k==='SHIFT'){alpha=false;shifted=!shifted;render();focus(active,selection[0]);return;}if(k==='C'){text='';natural.clear();syncNatural();result=null;error='';shifted=false;panelMode=null;render();focus();return;}
 if(mode==='natural'){if(shifted&&['←','→'].includes(k))natural.exit(k==='←'?'left':'right');else natural.key(k);syncNatural();shifted=false;result=null;error='';render();focus(active,selection[0]);return;}
 if(['←','→','↑','↓','OUT'].includes(k)){focus(active,Math.max(0,Math.min(text.length,selection[0]+(k==='←'?-1:k==='→'?1:0))));return;}if(k==='DEL'){let[a,b]=selection;if(a===b)a=Math.max(0,a-1);text=text.slice(0,a)+text.slice(b);render();focus(active,a);return;}
 if(k==='±'){text=text.startsWith('-(')&&text.endsWith(')')?text.slice(2,-1):'-('+text+')';render();focus();return;}
 const map={'∫':'integral(','d/dx':'derivative(','logₐ':'logbase(','°′″':'dms(','mixed':'mixed(','a/b':'/','xʸ':'^','x²':'^2','√':'sqrt(','ⁿ√':'root(','1/x':'^(-1)','10ˣ':'10^(','eˣ':'exp(','×10ⁿ':'×10^('};add(map[k]??(['sin','cos','tan','asin','acos','atan','log','ln','abs'].includes(k)?k+'(':k));}
 function render(){host.replaceChildren();host.classList.add('three-calculator');host.onkeydown=e=>{e.stopPropagation();const v=mode==='natural'?fields(tree).find(f=>f.id===active)?.text||'':text;
 if(e.key==='Escape'){e.preventDefault();onClose();return;}
 if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='a'){e.preventDefault();selection=[0,v.length];if(mode==='natural')natural.selection=[...selection];return;}
 if(e.ctrlKey||e.metaKey||e.altKey)return;
 if(e.key==='Enter'&&e.target.tagName!=='BUTTON'){e.preventDefault();solve();return;}
 if(e.key==='Backspace'||e.key==='Delete'){e.preventDefault();if(mode==='natural'){key(e.key==='Delete'?'Delete':'DEL');return;}if(e.key==='Delete'&&selection[0]===selection[1]){if(selection[0]>=v.length)return;selection[1]=selection[0]+1;}key('DEL');return;}
 if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();if(e.key==='Home'||e.key==='End')focus(active,e.key==='Home'?0:v.length);else if(mode==='natural'&&e.shiftKey&&['ArrowLeft','ArrowRight'].includes(e.key)){natural.exit(e.key==='ArrowLeft'?'left':'right');syncNatural();render();focus(active,selection[0]);}else if(mode==='natural')key({ArrowLeft:'←',ArrowRight:'→',ArrowUp:'↑',ArrowDown:'↓'}[e.key]);else focus(active,Math.max(0,Math.min(v.length,selection[0]+(e.key==='ArrowLeft'?-1:e.key==='ArrowRight'?1:0))));return;}
 if(e.key.length===1&&/[0-9a-zA-Z.+*/^!%,()−÷×π-]/.test(e.key)){e.preventDefault();if(mode==='natural'&&['(',')','^'].includes(e.key))key(e.key==='^'?'xʸ':e.key);else add(e.key);}
 };

 const bar=el('div','calc-modes');for(const [m,en,bm]of[['basic','Basic','Asas'],['scientific','Scientific','Saintifik'],['natural','Natural','Paparan Semula Jadi']]){const b=btn(tr(en,bm),()=>{if(m===mode)return;if(mode==='natural')text=serialize(tree);else if(m==='natural'){natural.clear();natural.type(text);syncNatural();}mode=m;remembered=m;try{sessionStorage.setItem('calculator-mode',m)}catch{}render();focus();});b.setAttribute('aria-pressed',String(mode===m));bar.append(b);}bar.append(btn(tr('Close calculator','Tutup kalkulator'),onClose,'×'));host.append(bar);
 if(mode!=='basic'){const units=el('div','calc-units');for(const v of['DEG','RAD']){const b=btn(v,()=>{angle=v;render();focus();});b.ariaLabel=v==='DEG'?tr('Degrees','Darjah'):tr('Radians','Radian');b.setAttribute('aria-pressed',String(v===angle));units.append(b);}host.append(units);}
 if(mode==='natural'){const editor=el('div','natural-editor');editor.setAttribute('role','group');editor.ariaLabel=tr('Natural expression','Ungkapan semula jadi');editor.append(treeDOM(tree));host.append(editor);}else{host.append(display('calc-linear',text,null,tr('Calculation','Pengiraan')));}
 const out=el('output','calc-result');out.setAttribute('aria-live','polite');host.append(out);const toggle=btn(tr('Fraction or decimal','Pecahan atau perpuluhan'),()=>{exact=!exact;output()},'S⇔D');toggle.className='calc-exact';toggle.disabled=!result?.exact;toggle.hidden=mode!=='basic';host.append(toggle);
 const displayNames={mixed:'a b/c',OUT:tr('OUT','KELUAR'),asin:'sin⁻¹',acos:'cos⁻¹',atan:'tan⁻¹',C:'AC','±':'(−)'};
 const makeKey=k=>{const b=btn(k,()=>key(k),displayNames[k]||k);b.dataset.key=k;if(k==='a/b'){const symbol=el('span','calc-key-fraction');symbol.append(el('span','','□'),el('span','','□'));b.replaceChildren(symbol);}if(k==='xʸ')b.replaceChildren(document.createTextNode('x'),el('sup','','□'));if(k==='C'||k==='DEL')b.className='calc-clear';return b;};
 if(mode!=='basic'){
 const controls=el('div','calc-hardware-controls');for(const k of ['SHIFT','ALPHA']){const b=makeKey(k);b.setAttribute('aria-pressed',String(k==='SHIFT'?shifted:alpha));controls.append(b);}const nav=el('div','calc-replay');for(const k of ['↑','←','→','↓']){const b=makeKey(k);b.dataset.direction=k;nav.append(b);}controls.append(nav,makeKey('MENU'),makeKey('ON'));host.append(controls);
 const functions=el('div','calc-functions calc-ex-layout');
 const rows=[['OPTN',null],['CALC',null],['∫','d/dx'],['x',null],['a/b','mixed'],['√','ⁿ√'],['x²','x³'],['xʸ','1/x'],['logₐ','log'],['ln','eˣ'],['±','abs','A'],['°′″',null,'B'],['1/x','!','C'],['sin','asin','D'],['cos','acos','E'],['tan','atan','F'],['STO','RCL'],['ENG','ENG←'],['(',null],[')',null,'x'],['S⇔D',null,'y'],['M+','M−','M']];
 rows.forEach(([base,alternate,letter],i)=>{const k=alpha&&letter?letter:shifted&&alternate?alternate:base,b=alpha&&letter?btn(tr('Variable ','Pemboleh ubah ')+k,()=>{alpha=shifted=false;add(k);},k):makeKey(k);if(i===2)b.style.gridColumn='5';if(i===3)b.style.gridColumn='6';if(k==='S⇔D'){b.ariaLabel=tr('Fraction or decimal','Pecahan atau perpuluhan');b.disabled=!result?.exact;}const caption=el('small','calc-secondary',displayNames[alternate]||alternate||' ');if(letter)caption.append(el('span','calc-alpha-caption',letter));b.prepend(caption);functions.append(b);});host.append(functions);
 }else{const functions=el('div','calc-functions');for(const k of ['(',')','±','%'])functions.append(makeKey(k));host.append(functions);}
 if(panelMode){const extra=el('section','calc-extra');extra.append(el('strong','',panelMode==='MENU'?tr('Calculation settings','Tetapan pengiraan'):panelMode==='CALC'?tr('Variable values','Nilai pemboleh ubah'):panelMode));
 if(panelMode==='CALC'){const source=mode==='natural'?serialize(tree):text,vars=[...new Set((source.match(/[A-Za-z]+/g)||[]).filter(name=>Object.hasOwn(memory,name)))];for(const name of vars){const l=el('label','',name),input=el('input');input.type='number';input.value=memory[name];input.ariaLabel=tr('Value of ','Nilai ')+name;input.onchange=()=>{if(Number.isFinite(+input.value))memory[name]=+input.value;};l.append(input);extra.append(l);}extra.append(btn(tr('Calculate','Kira'),()=>{panelMode=null;solve();render();},tr('Calculate','Kira')));}
 else if(['STO','RCL'].includes(panelMode)){for(const name of Object.keys(memory))extra.append(btn(tr(panelMode==='STO'?'Store ':'Recall ',panelMode==='STO'?'Simpan ':'Panggil ')+name,()=>{const store=panelMode==='STO';panelMode=null;if(store){solve();if(result)memory[name]=result.value;render();}else add(name);},name+' = '+Number(memory[name].toPrecision(8))));}
 else if(panelMode==='MENU'){extra.append(el('p','',tr('Scientific calculation · choose angle unit','Pengiraan saintifik · pilih unit sudut')));for(const v of ['DEG','RAD'])extra.append(btn(v,()=>{angle=v;panelMode=null;render();}));extra.append(el('p','',tr('∫ and d/dx use numerical approximations.','∫ dan d/dx menggunakan penghampiran berangka.')));}
 else for(const k of ['!','%','abs','log','10ˣ','eˣ','π','e','ⁿ√','mixed',',','OUT'])extra.append(makeKey(k));extra.append(btn(tr('Close options','Tutup pilihan'),()=>{panelMode=null;render();},'×'));host.append(extra);}
 const keys=el('div','calc-keys');['7','8','9','DEL','C','4','5','6','×','÷','1','2','3','+','−','0','.',mode==='basic'?'%':'×10ⁿ','Ans','='].forEach(k=>keys.append(makeKey(k)));host.append(keys);output();}
 render();return{refresh:render,focus:()=>{if(mode==='natural')focus();else focus(active,selection[0]);}};
}
